import numpy as np
from scipy.optimize import minimize

def objective(p):
    x, y, z = p
    return -(x*y**3 + y*z**3 + z*x**3)

def constraint(p):
    x, y, z = p
    return x**2 + y**2 + z**2 - 3

results = []
for i in range(-2, 3):
    for j in range(-2, 3):
        for k in range(-2, 3):
            p0 = np.array([i, j, k], dtype=float)
            norm = np.linalg.norm(p0)
            if norm < 1e-6: continue
            p0 = p0 * (np.sqrt(3) / norm)

            res = minimize(objective, p0, constraints={'type': 'eq', 'fun': constraint})
            if res.success:
                results.append(res.fun)

print(f"Maximum values found (negated): {np.max(results)}")
print(f"Minimum values found (negated): {np.min(results)}")

import numpy as np
from scipy.optimize import fsolve

def system(p):
    x, y, z = p
    return [
        y**3 + 3*z*x**2 - 4*x,
        3*x*y**2 + z**3 - 4*y,
        3*y*z**2 + x**3 - 4*z
    ]

def find_all_solutions():
    solutions = []
    # A more dense grid to be sure.
    for i in np.linspace(-1.8, 1.8, 20):
        for j in np.linspace(-1.8, 1.8, 20):
            for k in np.linspace(-1.8, 1.8, 20):
                p0 = np.array([i, j, k])
                norm = np.linalg.norm(p0)
                if norm < 1e-6: continue
                p0 = p0 * (np.sqrt(3) / norm)

                sol = fsolve(system, p0)
                x, y, z = sol
                if np.isclose(x**2 + y**2 + z**2, 3) and np.isclose(x*y**3 + y*z**3 + z*x**3, 3):
                    is_new = True
                    for sol2 in solutions:
                        if np.allclose(sol, sol2, atol=1e-4):
                            is_new = False
                            break
                    if is_new:
                        solutions.append(sol)
    return solutions

sols = find_all_solutions()
print(f"Number of solutions found: {len(sols)}")
for s in sols:
    print(s)

